"""RFC 7386 JSON Merge Patch: apply and diff.

Usage:
    mergepatch.py apply TARGET.json PATCH.json   # prints patched document
    mergepatch.py diff A.json B.json             # prints a merge patch that
                                                 # transforms A into B
"""

from __future__ import annotations

import copy
import json
import sys


def apply_merge_patch(target, patch):
    """Apply a JSON Merge Patch (RFC 7386, Section 2) to a target document.

    Implements the reference algorithm:

        define MergePatch(Target, Patch):
          if Patch is an Object:
            if Target is not an Object:
              Target = {}  # Ignore the contents and set it to an empty Object
            for each Name/Value pair in Patch:
              if Value is null:
                if Name exists in Target:
                  remove the Name/Value pair from Target
              else:
                Target[Name] = MergePatch(Target[Name], Value)
            return Target
          else:
            return Patch
    """
    if isinstance(patch, dict):
        if isinstance(target, dict):
            result = copy.deepcopy(target)
        else:
            # Ignore the contents of Target and set it to an empty Object.
            result = {}
        for name, value in patch.items():
            if value is None:
                if name in result:
                    del result[name]
            else:
                result[name] = apply_merge_patch(result.get(name), value)
        return result
    # A non-object patch replaces the target entirely.
    return copy.deepcopy(patch)


def diff(a, b):
    """Produce a JSON Merge Patch P such that apply(a, P) == b.

    Exact round-tripping is guaranteed whenever b contains no null values,
    because in RFC 7386 a null inside an object-valued patch means "remove",
    so JSON nulls in b are unrepresentable.
    """
    if isinstance(b, dict):
        if isinstance(a, dict):
            patch = {}
            for key, value in b.items():
                if key in a:
                    patch[key] = diff(a[key], value)
                else:
                    patch[key] = copy.deepcopy(value)
            for key in a:
                if key not in b:
                    patch[key] = None  # removal
            return patch
        # b is an object but a is not: the patch object itself fully replaces a.
        return copy.deepcopy(b)
    # Arrays and scalars are replaced wholesale (RFC 7386: arrays are not merged).
    return copy.deepcopy(b)


def _load_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    usage = (
        "usage:\n"
        "  mergepatch.py apply TARGET.json PATCH.json\n"
        "  mergepatch.py diff A.json B.json"
    )
    if len(argv) != 3 or argv[0] not in ("apply", "diff"):
        print(usage, file=sys.stderr)
        return 2

    command = argv[0]
    try:
        if command == "apply":
            target = _load_json(argv[1])
            patch = _load_json(argv[2])
            document = apply_merge_patch(target, patch)
        else:
            a = _load_json(argv[1])
            b = _load_json(argv[2])
            document = diff(a, b)
    except (OSError, json.JSONDecodeError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    print(json.dumps(document, indent=2, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    sys.exit(main())
